export function sliceMoney(pence: number): string {
  const sign = pence < 0 ? "−" : "";
  const n = Math.abs(pence);
  return `${sign}${Math.floor(n / 240)}镑 ${Math.floor((n % 240) / 12)}苏勒 ${n % 12}便士`;
}
const displayNumber = (n: number) =>
  Number.isInteger(n) ? String(n) : n.toFixed(1);
const signed = (n: number) => `${n > 0 ? "+" : ""}${displayNumber(n)}`;
const dateText = (date: SliceProjection["date"]) =>
  `第五纪 ${date.year}年${date.month}月${date.day}日`;
const assetPath = (path: string) => `${import.meta.env.BASE_URL}assets/${path}`;
const portraitPath = (id: string) =>
  assetPath(
    `portraits/portrait_${id.replace("portrait-", "").padStart(2, "0")}.webp`,
  );
