function Meter({
  label,
  current,
  max,
}: {
  label: string;
  current: number;
  max: number;
}) {
  return (
    <div className="slice-meter">
      <div className="slice-meter-head">
        <span>{label}</span>
        <span>
          {current} / {max}
        </span>
      </div>
      <div
        className="slice-meter-track"
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={current}
      >
        <span
          style={{
            width: `${Math.max(0, Math.min(100, (current / max) * 100))}%`,
          }}
        />
      </div>
    </div>
  );
}
function Modal({
  title,
  children,
  onClose,
  blocking = false,
  className = "",
}: {
  title: string;
  children: ReactNode;
  onClose?: () => void;
  blocking?: boolean;
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const before = document.activeElement as HTMLElement | null;
    const node = ref.current;
    if (!node) return;
    const heading = node.querySelector<HTMLElement>("[data-modal-heading]");
    (heading ?? node).focus();
    return () => { if (before?.isConnected) before.focus({ preventScroll: true }); };
  }, [title]);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const trap = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        if (!blocking) onClose?.();
      }
      if (event.key !== "Tab") return;
      const targets = Array.from(
        node.querySelectorAll<HTMLElement>(
          'button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary,[tabindex="0"]',
        ),
      );
      if (!targets.length) {
        event.preventDefault();
        node.focus();
        return;
      }
      const first = targets[0];
      const last = targets[targets.length - 1];
      if (
        event.shiftKey &&
        (document.activeElement === first ||
          !targets.includes(document.activeElement as HTMLElement))
      ) {
        event.preventDefault();
        last?.focus();
      } else if (
        !event.shiftKey &&
        (document.activeElement === last ||
          !targets.includes(document.activeElement as HTMLElement))
      ) {
        event.preventDefault();
        first?.focus();
      }
    };
    document.addEventListener("keydown", trap);
    return () => {
      document.removeEventListener("keydown", trap);
    };
  }, [blocking, onClose]);
  return (
    <div className="slice-overlay">
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-label={title}
        tabIndex={-1}
        className={`slice-dialog ${className}`}
      >
        {children}
      </div>
      <span className="slice-scroll-hint">可在卷宗内滚动阅读全部内容</span>
    </div>
  );
}
function DialogHeading({
  title,
  onClose,
}: {
  title: string;
  onClose?: () => void;
}) {
  return (
    <div className="slice-dialog-header">
      <h2 tabIndex={-1} data-modal-heading>
        {title}
      </h2>
      {onClose && (
        <button
          className="slice-button quiet"
          onClick={onClose}
          aria-label={`关闭${title}`}
        >
          关闭
        </button>
      )}
    </div>
  );
}
function CheckDetails({ check }: { check: PublicCheckResult }) {
  return (
    <div className="slice-round-record">
      <h3>
        {QUALITY[check.tier]} ·{" "}
        {STATS.find((s) => s.key === check.ability)?.label}检定
      </h3>
      <p>
        基础 {check.baseAbility}，有效能力 {check.effectiveAbility}，难度{" "}
        {check.difficulty}。成功率 {check.chance}%，d100 掷骰 {check.roll}。
      </p>
      {check.modifiers.length > 0 && (
        <ul className="slice-simple-list">
          {check.modifiers.map((m, i) => (
            <li key={`${m.source}-${i}`}>
              {m.source} {signed(m.value)}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function Creation({
  onCreate,
  onBack,
  busy,
  error,
  onRetry,
}: {
  onCreate: (selection: SliceCreationSelection) => void;
  onBack: () => void;
  busy: boolean;
  error: SliceError | null;
  onRetry: () => void;
}) {
  const [step, setStep] = useState(0);
  const [selection, setSelection] = useState<SliceCreationSelection>({
    ...sliceDefaultCreationSelection,
    traitIds: [...sliceDefaultCreationSelection.traitIds],
    acceptedConditionIds: [
      ...sliceDefaultCreationSelection.acceptedConditionIds,
    ],
  });
  useEffect(() => {
    document.getElementById("creation-step-title")?.focus();
  }, [step]);
  const preview = previewSliceCreation(selection);
  const origin = sliceCreationCatalogue.origins.find(
    (o) => o.id === selection.originId,
  )!;
  const profession = sliceCreationCatalogue.professions.find(
    (p) => p.id === selection.professionId,
  );
  const compatibility = sliceCreationCatalogue.compatibility.find(
    (c) =>
      c.originId === selection.originId &&
      c.professionId === selection.professionId,
  );
  const validation = validateSliceCreation(selection);
  function update(patch: Partial<SliceCreationSelection>) {
    setSelection((current) => ({ ...current, ...patch }));
  }
  function chooseOrigin(id: string) {
    const o = sliceCreationCatalogue.origins.find((x) => x.id === id)!;
    const rules = sliceCreationCatalogue.compatibility.filter(
      (x) => x.originId === id,
    );
    const first = rules.find((x) => x.status === "DIRECT");
    update({
      originId: id,
      professionId: first?.professionId ?? selection.professionId,
      acceptedConditionIds: [],
      educationLevel: o.opening.defaultEducation,
      livingStandardId: o.opening.defaultLivingStandardId,
    });
  }
  function stepErrors(): string[] {
    if (step === 0) {
      const errors = [];
      if (!selection.displayName.trim()) errors.push("请填写姓名。");
      if (
        !Number.isInteger(selection.age) ||
        selection.age < 18 ||
        selection.age > 45
      )
        errors.push("年龄须为18至45岁的整数。");
      return errors;
    }
    if (
      step === 2 &&
      compatibility?.status === "CONDITIONAL" &&
      !selection.acceptedConditionIds.includes(compatibility.conditionId!)
    )
      return ["请阅读并接受这项职业的前提和代价。"];
    if (step === 3 && !validation.ok) return [...validation.errors];
    return [];
  }
  const localErrors = stepErrors();
  const changeStep = (n: number) => {
    setStep(n);
    window.scrollTo?.({ top: 0, behavior: "instant" });
  };
  return (
    <div className="slice-creation">
      <div className="slice-creation-heading">
        <div>
          <div className="slice-eyebrow">一份新的个人卷宗</div>
          <h2>从普通人的生活开始</h2>
        </div>
        <button
          className="slice-button quiet"
          onClick={onBack}
          disabled={busy || error !== null}
        >
          返回标题
        </button>
      </div>
      <ol className="slice-step-list" aria-label="角色创建步骤">
        {STEPS.map((label, i) => (
          <li key={label}>
            <button
              onClick={() => changeStep(i)}
              aria-current={i === step ? "step" : undefined}
              disabled={busy}
            >
              <span className="slice-step-number">{i + 1}</span>
              {label}
            </button>
          </li>
        ))}
      </ol>
      <div className="slice-creation-layout">
        <section
          className="slice-creation-main slice-paper"
          aria-labelledby="creation-step-title"
        >
          <div className="slice-creation-scroll">
            <div className="slice-eyebrow">第 {step + 1} / 6 步</div>
            <h2 id="creation-step-title" tabIndex={-1}>
              {STEPS[step]}
            </h2>
            {step === 0 && (
              <>
                <p className="slice-muted">
                  出生于鲁恩，现在住在贝克兰德。肖像只改变外观。
                </p>
                <div className="slice-form-grid">
                  <label className="slice-field">
                    <span>姓名</span>
                    <input
                      maxLength={24}
                      value={selection.displayName}
                      onChange={(e) => update({ displayName: e.target.value })}
                    />
                  </label>
                  <label className="slice-field">
                    <span>年龄</span>
                    <input
                      type="number"
                      min={18}
                      max={45}
                      value={selection.age}
                      onChange={(e) => update({ age: Number(e.target.value) })}
                    />
                  </label>
                  <label className="slice-field">
                    <span>性别</span>
                    <select
                      value={selection.sex}
                      onChange={(e) =>
                        update({
                          sex: e.target.value as SliceCreationSelection["sex"],
                        })
                      }
                    >
                      <option value="FEMALE">女性</option>
                      <option value="MALE">男性</option>
                    </select>
                  </label>
                  <label className="slice-field">
                    <span>出生地</span>
                    <select
                      value={selection.birthplaceId}
                      onChange={(e) => update({ birthplaceId: e.target.value })}
                    >
                      {sliceCreationCatalogue.birthplaces.map((b) => (
                        <option key={b.id} value={b.id}>
                          {b.label}
                        </option>
                      ))}
                    </select>
                  </label>
                </div>
                <h3 style={{ marginTop: 24 }}>选择肖像</h3>
                <div className="slice-portrait-grid" aria-label="八款预设肖像">
                  {sliceCreationCatalogue.portraits.map((p) => (
                    <button
                      className="slice-portrait-choice"
                      key={p.id}
                      aria-pressed={selection.portraitId === p.id}
                      onClick={() => update({ portraitId: p.id })}
                    >
                      <img src={portraitPath(p.id)} alt={p.label} />
                      <span>
                        {p.label}
                        {selection.portraitId === p.id ? " · 已选" : ""}
                      </span>
                    </button>
                  ))}
                </div>
                <label className="slice-field full">
                  <span>简短外貌描述（可选）</span>
                  <textarea
                    maxLength={120}
                    value={selection.appearanceDescription}
                    onChange={(e) =>
                      update({ appearanceDescription: e.target.value })
                    }
                  />
                  <small className="slice-muted">
                    仅写入履历，不改变能力。最多120字。
                  </small>
                </label>
              </>
            )}
            {step === 1 && (
              <>
                <p className="slice-muted">
                  成长背景决定家庭、关系与开局条件。随时可以返回修改。
                </p>
                <div className="slice-option-grid">
                  {sliceCreationCatalogue.origins.map((o) => (
                    <button
                      key={o.id}
                      className="slice-choice"
                      aria-pressed={selection.originId === o.id}
                      onClick={() => chooseOrigin(o.id)}
                    >
                      <small>{SOCIAL[o.tier]}</small>
                      <strong>{o.label}</strong>
                      <small>{o.summary}</small>
                      <span className="slice-modifiers">
                        {modifierText(o.opening.coreStatModifiers)}
                      </span>
                      <small>
                        默认 {EDUCATIONS[o.opening.defaultEducation]} · 家庭转交{" "}
                        {sliceMoney(o.opening.familyTransferPence)}
                      </small>
                      <small>
                        {o.opening.initialDebtPence > 0
                          ? `开局债务 ${sliceMoney(o.opening.initialDebtPence)}`
                          : "无开局债务"}
                      </small>
                    </button>
                  ))}
                </div>
                <h3>学历</h3>
                <div className="slice-option-grid">
                  <button
                    className="slice-choice"
                    aria-pressed={
                      selection.educationLevel ===
                      origin.opening.defaultEducation
                    }
                    onClick={() =>
                      update({
                        educationLevel: origin.opening.defaultEducation,
                      })
                    }
                  >
                    <strong>
                      {EDUCATIONS[origin.opening.defaultEducation]}
                    </strong>
                    <small>家庭提供的默认学历</small>
                    <span className="slice-modifiers">
                      知识 +
                      {sliceCreationCatalogue.educations.find(
                        (e) => e.id === origin.opening.defaultEducation,
                      )?.openingKnowledgeBonus ?? 0}{" "}
                      · 成功学习额外 +
                      {sliceCreationCatalogue.educations.find(
                        (e) => e.id === origin.opening.defaultEducation,
                      )?.learningKnowledgeBonus ?? 0}
                    </span>
                  </button>
                  {origin.opening.alternativeEducation && (
                    <button
                      className="slice-choice"
                      aria-pressed={
                        selection.educationLevel ===
                        origin.opening.alternativeEducation.level
                      }
                      onClick={() =>
                        update({
                          educationLevel:
                            origin.opening.alternativeEducation!.level,
                        })
                      }
                    >
                      <strong>
                        {EDUCATIONS[origin.opening.alternativeEducation.level]}
                      </strong>
                      <small>
                        {origin.opening.alternativeEducation.prerequisite}
                      </small>
                      <span className="slice-modifiers">
                        知识 +
                        {sliceCreationCatalogue.educations.find(
                          (e) =>
                            e.id === origin.opening.alternativeEducation?.level,
                        )?.openingKnowledgeBonus ?? 0}{" "}
                        · 成功学习额外 +
                        {sliceCreationCatalogue.educations.find(
                          (e) =>
                            e.id === origin.opening.alternativeEducation?.level,
                        )?.learningKnowledgeBonus ?? 0}
                      </span>
                      <span className="slice-modifiers">
                        开局资金 −
                        {sliceMoney(
                          origin.opening.alternativeEducation.costPence,
                        )}
                      </span>
                    </button>
                  )}
                </div>
                <h3>开局生活标准</h3>
                <p className="slice-muted">费用在周末结算。游戏中也可调整。</p>
                <div className="slice-option-grid">
                  {sliceCreationCatalogue.livingStandards.map((l) => (
                    <button
                      key={l.id}
                      className="slice-choice"
                      aria-pressed={selection.livingStandardId === l.id}
                      onClick={() => update({ livingStandardId: l.id })}
                    >
                      <strong>{l.label}</strong>
                      <small>{l.summary}</small>
                      <span className="slice-modifiers">
                        每周 {sliceMoney(l.weeklyCostPence)}
                      </span>
                      <small>
                        休养健康 +{l.restHealth} · 精神 +{l.restMind}
                      </small>
                    </button>
                  ))}
                </div>
              </>
            )}
            {step === 2 && (
              <>
                <p className="slice-muted">
                  这里只列出你的出身能够到达的职业。
                </p>
                <div className="slice-option-grid">
                  {sliceCreationCatalogue.professions.flatMap((p) => {
                    const rule = sliceCreationCatalogue.compatibility.find(
                      (c) =>
                        c.originId === selection.originId &&
                        c.professionId === p.id,
                    );
                    if (!rule || rule.status === "FORBIDDEN") return [];
                    return [
                      <button
                        key={p.id}
                        className="slice-choice"
                        aria-pressed={selection.professionId === p.id}
                        onClick={() =>
                          update({
                            professionId: p.id,
                            acceptedConditionIds: [],
                          })
                        }
                      >
                        <strong>{p.label}</strong>
                        <small>{p.summary}</small>
                        <span className="slice-modifiers">
                          {modifierText(p.opening.coreStatModifiers)}
                        </span>
                        <small>
                          开局个人资金 {sliceMoney(p.opening.initialCashPence)}
                        </small>
                        <small>
                          工作周薪 {sliceMoney(p.opening.weeklyWorkPayPence)}
                        </small>
                        {rule.status === "CONDITIONAL" && (
                          <small>
                            有条件 · {rule.publicReason} ·{" "}
                            {rule.conditionCostSummary}
                          </small>
                        )}
                      </button>,
                    ];
                  })}
                </div>
                {compatibility?.status === "CONDITIONAL" && (
                  <div className="slice-condition">
                    <h3>{profession?.label}的条件</h3>
                    <p>{compatibility.prerequisite}</p>
                    <p>{compatibility.publicReason}</p>
                    <p>
                      固定代价：{compatibility.conditionCostSummary}（
                      {sliceMoney(compatibility.costPence ?? 0)}）
                    </p>
                    <label className="slice-check-label">
                      <input
                        type="checkbox"
                        checked={selection.acceptedConditionIds.includes(
                          compatibility.conditionId!,
                        )}
                        onChange={(e) =>
                          update({
                            acceptedConditionIds: e.target.checked
                              ? [compatibility.conditionId!]
                              : [],
                          })
                        }
                      />
                      <span>我接受这个前提和代价</span>
                    </label>
                  </div>
                )}
              </>
            )}
            {step === 3 && (
              <>
                <p className="slice-muted">
                  恰好选两个特质，再选一个真实缺陷。缺陷不会给你额外点数。
                </p>
                <h3>性格特质 · 已选 {selection.traitIds.length} / 2</h3>
                <div className="slice-option-grid">
                  {sliceCreationCatalogue.traits.map((t) => {
                    const chosen = selection.traitIds.includes(t.id);
                    const conflict = selection.traitIds.some((id) =>
                      t.incompatibleTraitIds.includes(id),
                    );
                    return (
                      <button
                        key={t.id}
                        className="slice-choice"
                        aria-pressed={chosen}
                        disabled={
                          !chosen &&
                          (selection.traitIds.length >= 2 || conflict)
                        }
                        onClick={() =>
                          update({
                            traitIds: chosen
                              ? selection.traitIds.filter((id) => id !== t.id)
                              : [...selection.traitIds, t.id],
                          })
                        }
                      >
                        <strong>{t.label}</strong>
                        <small>{t.summary}</small>
                        <span className="slice-modifiers">
                          {modifierText(t.coreStatModifiers)}
                        </span>
                        {conflict && !chosen && <small>与已选特质冲突</small>}
                      </button>
                    );
                  })}
                </div>
                <h3>真实缺陷 · 选择一个</h3>
                <div className="slice-option-grid">
                  {sliceCreationCatalogue.flaws.map((f) => (
                    <button
                      key={f.id}
                      className="slice-choice"
                      aria-pressed={selection.flawId === f.id}
                      onClick={() => update({ flawId: f.id })}
                    >
                      <strong>{f.label}</strong>
                      <small>{f.summary}</small>
                      <span className="slice-modifiers">
                        {modifierText(f.coreStatModifiers)}
                      </span>
                    </button>
                  ))}
                </div>
              </>
            )}
            {(step === 4 || step === 5) && (
              <>
                <p className="slice-muted">
                  {step === 4
                    ? "这是只读摘要。需要修改时，点上方步骤返回。"
                    : "确认后，这份履历将成为你在贝克兰德的起点。"}
                </p>
                <div className="slice-summary-grid">
                  <dl className="slice-definition">
                    <dt>姓名与身份</dt>
                    <dd>
                      {selection.displayName} · {selection.age}岁 ·{" "}
                      {selection.sex === "FEMALE" ? "女性" : "男性"}
                    </dd>
                    <dt>出生地</dt>
                    <dd>
                      {
                        sliceCreationCatalogue.birthplaces.find(
                          (b) => b.id === selection.birthplaceId,
                        )?.label
                      }
                    </dd>
                    <dt>出身与职业</dt>
                    <dd>
                      {origin.label} · {profession?.label}
                    </dd>
                    <dt>学历</dt>
                    <dd>
                      {EDUCATIONS[selection.educationLevel]} · 成功学习额外知识
                      +{preview.learningKnowledgeBonus}
                    </dd>
                    <dt>人格</dt>
                    <dd>
                      {selection.traitIds
                        .map(
                          (id) =>
                            sliceCreationCatalogue.traits.find(
                              (t) => t.id === id,
                            )?.label,
                        )
                        .join("、")}
                      ；
                      {
                        sliceCreationCatalogue.flaws.find(
                          (f) => f.id === selection.flawId,
                        )?.label
                      }
                    </dd>
                  </dl>
                  <dl className="slice-definition">
                    <dt>初始资金</dt>
                    <dd>{sliceMoney(preview.cashBreakdown.totalPence)}</dd>
                    <dt>工作周薪</dt>
                    <dd>{sliceMoney(preview.weeklyWorkPayPence)}</dd>
                    <dt>家庭债务</dt>
                    <dd>
                      {sliceMoney(preview.initialDebtPence)}
                      {preview.initialDebtPence > 0 &&
                        ` · 每周偿还 ${sliceMoney(preview.debtWeeklyRepaymentPence)}`}
                    </dd>
                    <dt>生活标准</dt>
                    <dd>{TIERS[selection.livingStandardId]}</dd>
                    <dt>支持关系</dt>
                    <dd>{origin.opening.supportLabel}</dd>
                    <dt>义务与风险</dt>
                    <dd>{origin.opening.obligationLabel}</dd>
                  </dl>
                </div>
                <hr className="slice-rule" />
                <h3>资金来源</h3>
                <ul className="slice-simple-list">
                  <li>
                    职业个人资金：
                    {sliceMoney(preview.cashBreakdown.professionInitialPence)}
                  </li>
                  <li>
                    家庭一次性转交：
                    {sliceMoney(preview.cashBreakdown.familyTransferPence)}
                  </li>
                  <li>
                    职业前提费用：−
                    {sliceMoney(preview.cashBreakdown.conditionCostPence)}
                  </li>
                  <li>
                    替代学历费用：−
                    {sliceMoney(preview.cashBreakdown.educationCostPence)}
                  </li>
                </ul>
                <p className="slice-notice">
                  开局为普通人，健康100、精神100、灵性15，每周3次行动。第一周有一张出身事件，处理事件不额外消耗行动。
                </p>
                {step === 5 && (
                  <p>
                    推荐第一周：工作 → 调查街区告示 → 休养。你也可以自由安排。
                  </p>
                )}
              </>
            )}
            {localErrors.length > 0 && (
              <div className="slice-notice slice-error" role="status">
                {localErrors.map((e) => (
                  <div key={e}>{e}</div>
                ))}
              </div>
            )}
            {step === 5 && !validation.ok && (
              <div className="slice-notice slice-error" role="status">
                {validation.errors.map((e) => (
                  <div key={e}>{e}</div>
                ))}
              </div>
            )}
            {error && (
              <ErrorNotice error={error} onRetry={onRetry} busy={busy} />
            )}
          </div>
          <div className="slice-navigation">
            <button
              className="slice-button quiet"
              onClick={() => changeStep(step - 1)}
              disabled={step === 0 || busy}
            >
              上一步
            </button>
            <small className="slice-muted">向下滚动可查看完整选项</small>
            {step < 5 ? (
              <button
                className="slice-button primary"
                disabled={localErrors.length > 0 || busy}
                onClick={() => changeStep(step + 1)}
              >
                下一步
              </button>
            ) : (
              <button
                className="slice-button primary"
                disabled={!validation.ok || busy}
                onClick={() => onCreate(selection)}
              >
                {busy ? "正在建立卷宗…" : "确认，开始生活"}
              </button>
            )}
          </div>
        </section>
        <aside
          className="slice-creation-preview slice-paper"
          aria-label="实时开局预览"
        >
          <h3>开局预览</h3>
          <img
            className="slice-portrait"
            src={portraitPath(selection.portraitId)}
            alt="当前选择的角色肖像"
          />
          <div className="slice-stat-list" aria-live="polite">
            {STATS.map((s) => (
              <div key={s.key} className="slice-stat">
                <span>{s.label}</span>
                <strong>{preview.coreStats[s.key]}</strong>
              </div>
            ))}
          </div>
          <details className="slice-stat-sources">
            <summary>查看能力来源</summary>
            {preview.statSources.map((source) => (
              <p key={source.id} className="slice-sources">
                {source.label}：{modifierText(source.modifiers)}
              </p>
            ))}
          </details>
          <hr className="slice-rule" />
          <div>
            <small className="slice-muted">初始资金</small>
            <p>{sliceMoney(preview.cashBreakdown.totalPence)}</p>
            <small className="slice-muted">
              条件费用只作预览，确认前不扣款。
            </small>
          </div>
          <button
            className="slice-button quiet"
            onClick={() => {
              setSelection({
                ...sliceDefaultCreationSelection,
                traitIds: [...sliceDefaultCreationSelection.traitIds],
                acceptedConditionIds: [],
              });
            }}
            disabled={busy}
            style={{ marginTop: 16 }}
          >
            使用可编辑推荐组合
          </button>
        </aside>
      </div>
    </div>
  );
}
function ErrorNotice({
  error,
  onRetry,
  busy,
}: {
  error: SliceError;
  onRetry: () => void;
  busy: boolean;
}) {
  return (
    <div className="slice-notice slice-error" role="alert">
      <p>{playerText(error.message)}</p>
      <small>这次操作尚未确认保存，当前进度保持不变。</small>
      <div style={{ marginTop: 12 }}>
        <button className="slice-button" onClick={onRetry} disabled={busy}>
          {busy
            ? "正在重试…"
            : error.retryable
              ? "重试这次操作"
              : "重新读取卷宗"}
        </button>
      </div>
    </div>
  );
}
function Chronicle({ state }: { state: SliceProjection }) {
  return (
    <ol className="slice-chronicle">
      {state.chronicle.map((record) => (
        <li key={record.id}>
          <small className="slice-muted">第 {record.week} 周</small>
          <h3>{record.title}</h3>
          <p>{seerReadableText(record.text)}</p>
        </li>
      ))}
    </ol>
  );
}
function Details({
  state,
  onCommand,
  busy,
}: {
  state: SliceProjection;
  onCommand: (command: SliceCommand) => void;
  busy: boolean;
}) {
  return (
    <div className="slice-details-grid">
      <section>
        <h3>人物履历</h3>
        <dl className="slice-definition">
          <dt>姓名</dt>
          <dd>
            {state.character.name} · {state.character.age}岁
          </dd>
          <dt>出生地</dt>
          <dd>{state.character.birthplace.label}</dd>
          <dt>出身</dt>
          <dd>{state.character.originName}</dd>
          <dt>当前职业</dt>
          <dd>{state.character.professionName}</dd>
          <dt>学历</dt>
          <dd>
            {EDUCATIONS[state.character.education] ?? state.character.education}
          </dd>
          <dt>人格</dt>
          <dd>
            {state.character.traits.map((t) => t.label).join("、")}；缺陷：
            {state.character.flaw.label}
          </dd>
          <dt>外貌描述</dt>
          <dd>{state.character.appearanceDescription || "未填写"}</dd>
          <dt>身份</dt>
          <dd>{pathwayTitle(state)} · 未加入正式组织</dd>
        </dl>
        <div className="slice-stat-list">
          {STATS.map((s) => (
            <div className="slice-stat" key={s.key}>
              <span>{s.label}</span>
              <strong>{state.character.coreStats[s.key]}</strong>
            </div>
          ))}
        </div>
      </section>
      <section>
        <h3>身心与伤势</h3>
        <Meter label="健康" current={state.health} max={state.maxHealth} />
        <Meter label="精神" current={state.mind} max={state.maxMind} />
        <Meter
          label="灵性"
          current={state.spirituality}
          max={state.maxSpirituality}
        />
        <p>污染 {state.pollution}</p>
        {state.injuries.length > 0 ? (
          <ul className="slice-simple-list">
            {state.injuries.map((injury, i) => (
              <li key={injury.id}>
                {i + 1}. {injury.severity === "HEAVY" ? "重伤" : "轻伤"} ·{" "}
                {injury.treatedRevision === null
                  ? "尚未处置"
                  : "已处置，仍须休养至真正痊愈"}
              </li>
            ))}
          </ul>
        ) : (
          <p className="slice-muted">当前没有普通伤势。</p>
        )}
        <p className="slice-muted">累计受伤风险层数 {state.injuryRisk}</p>
      </section>
      <section>
        <h3>生活账目</h3>
        <dl className="slice-definition">
          <dt>现金</dt>
          <dd>{sliceMoney(state.cash)}</dd>
          <dt>工作周薪</dt>
          <dd>
            {sliceMoney(state.weeklyWage)} ·{" "}
            {state.wagePaid ? "本周已支付" : "本周尚未工作领取"}
          </dd>
          <dt>当前生活标准</dt>
          <dd>{TIERS[state.lifeTier]}</dd>
          <dt>下周生活标准</dt>
          <dd>{TIERS[state.nextLifeTier]}</dd>
          <dt>债务总额</dt>
          <dd>{sliceMoney(state.debtTotal)}</dd>
        </dl>
        <details style={{ marginTop: 18 }}>
          <summary>查看开局资金与前提</summary>
          <ul className="slice-simple-list">
            <li>
              职业个人资金{" "}
              {sliceMoney(state.character.creationCosts.professionInitialPence)}
            </li>
            <li>
              家庭一次性转交{" "}
              {sliceMoney(state.character.creationCosts.familyTransferPence)}
            </li>
            <li>
              职业前提费用 −
              {sliceMoney(state.character.creationCosts.conditionCostPence)}
            </li>
            <li>
              替代学历费用 −
              {sliceMoney(state.character.creationCosts.educationCostPence)}
            </li>
            {state.character.acceptedConditionIds.map((id) => {
              const condition = sliceCreationCatalogue.conditions.find(
                (c) => c.id === id,
              );
              return condition ? (
                <li key={id}>
                  已接受：{condition.prerequisite} ·{" "}
                  {sliceMoney(condition.costPence)}
                </li>
              ) : null;
            })}
          </ul>
        </details>
        {state.debts.map((debt) => (
          <div key={debt.id} className="slice-condition">
            <p>
              {debt.source}：{sliceMoney(debt.remaining)}
            </p>
            <small>每周应付 {sliceMoney(debt.weeklyPayment)}</small>
            {state.canAct && state.cash > 0 && (
              <button
                className="slice-button quiet"
                style={{ marginTop: 10 }}
                disabled={busy}
                onClick={() =>
                  onCommand({
                    type: "REPAY",
                    amount: Math.min(state.cash, debt.remaining),
                  })
                }
              >
                偿还 {sliceMoney(Math.min(state.cash, debt.remaining))}
              </button>
            )}
          </div>
        ))}
      </section>
      <section>
        <h3>已知信息</h3>
        {state.knowledge.length > 0 ? (
          <ul className="slice-simple-list">
            {state.knowledge.map((k) => (
              <li key={k.id}>
                <strong>{k.title}</strong>
                <p>{k.text}</p>
                <small className="slice-muted">第 {k.week} 周获知</small>
              </li>
            ))}
          </ul>
        ) : (
          <p className="slice-muted">目前只知道街区里的普通告示。</p>
        )}
        {state.aidCanCancel && (
          <button
            className="slice-button quiet"
            disabled={busy}
            onClick={() => onCommand({ type: "CANCEL_AID" })}
          >
            取消诊疗援助委托
          </button>
        )}
      </section>
    </div>
  );
}
type PaleEmperorCombatProjection = NonNullable<SliceProjection["combat"]>["paleEmperor"];
function PaleEmperorActionSequence({actions}:{actions:NonNullable<PaleEmperorCombatProjection>["lastActionSequence"]}) {
 return <ol>{actions.map(action=><li key={`${action.actor}-${action.order}`}>
  <strong>{action.actor==="PLAYER"?"本人":"对手"}第{action.order+1}槽：{action.label}</strong>
  <p>实耗{action.paidCost}灵性、{action.mindCost}精神；自身优势{displayNumber(action.selfGain)}，减势{displayNumber(action.enemyReduction)}。本槽实际经过{action.elapsedSeconds}秒。</p>
  {action.fallbackReason&&<p>{action.fallbackReason}</p>}
  {action.check&&<p>检定骰{action.check.roll}，成功率{action.check.chance}%；对手抵抗{action.resistanceRoll===null?"本次未触发":`${action.resistanceRoll}/${action.resistanceChance}%`}。</p>}
  {action.finiteResult==="PENDING"&&<p>当前只是建立有限窗口，尚未对后续动作生效。</p>}
  {action.finiteResult==="APPLIED"&&<p>有限窗口已经在这个实际动作中消耗。</p>}
  <p>本槽原灵印消耗{action.spiritMarksSpent}；普通移动{action.travelMetres}米。现场条件{action.conditionVersionBefore}→{action.conditionVersionAfter}。</p>
  <p>本人精神{action.playerMindAfter}、灵性{action.playerSpiritualityAfter}；对手精神{action.enemyMindAfter}、灵性{action.enemySpiritualityAfter}。</p>
 </li>)}</ol>;
}
