function natureWalkerProse(text: string, characterName?: string): string {
  const tiers: Record<string, string> = { GREAT_SUCCESS: "大成功", SUCCESS: "成功", GREAT_FAILURE: "严重失败", FAILURE: "失败" };
  const authored = (part: string) => playerText(part).replace(/\b(GREAT_SUCCESS|SUCCESS|GREAT_FAILURE|FAILURE)\b/g, tier => tiers[tier]!);
  return characterName ? text.split(characterName).map(authored).join(characterName) : authored(text);
}

function handOfOrderProse(text: string, characterName?: string): string {
  const tiers: Record<string, string> = { GREAT_SUCCESS: "大成功", SUCCESS: "成功", GREAT_FAILURE: "严重失败", FAILURE: "失败" };
  const authored = (part: string) => playerText(part).replace(/\b(GREAT_SUCCESS|SUCCESS|GREAT_FAILURE|FAILURE)\b/g, tier => tiers[tier]!);
  return characterName ? text.split(characterName).map(authored).join(characterName) : authored(text);
}

function HandOfOrderActionSequence({ actions, characterName }: { actions: HandOfOrderCombatProjection["lastActionSequence"]; characterName?: string }) {
  const attack: Record<string, string> = { NONE: "本槽没有直接攻击", BODY: "实际身体打击", ARC: "实际弧光冲击，按身体后果处理", MIND: "实际精神压力，不生成身体伤口" };
  const fallback: Record<string, string> = {
    POLICY: "本次选择不使用此术，按普通行动处理。",
    ACTIVE_WINDOW: "同一待用作用仍有效，本次不重复施术或收费。",
    INSUFFICIENT_RESOURCES: "实际资源不足，采用普通替代，不透支或补发物品。",
    S2_RESOURCES_UNAVAILABLE: "本次条件不足，按实际资源执行继承能力。",
    PENDING_OR_RESOURCES: "已有未用影响或资源不足，本次普通观察。",
    NO_EXTENDABLE_OWN_EFFECT: "没有本人仍可延长的待用影响，或资源不足。",
    FINITE_ENEMY_RESOURCES_UNAVAILABLE: "对手的有限资源不足，本次沿实际原杖作身体攻击。",
  };
  return actions.length > 0 && <ol aria-label="秩序之手实际动作">{actions.map(action => <li key={`${action.actor}-${action.order}`}>
    <strong>{action.actor === "PLAYER" ? "本人" : "对手"}第{action.order + 1}槽：{handOfOrderProse(action.label, characterName)}</strong>
    <p>实耗{action.paidCost}灵性、{action.mindCost}精神；自身优势{displayNumber(action.selfGain)}，减势{displayNumber(action.enemyReduction)}。现场第{action.atSeconds}秒开始，实际经过{action.elapsedSeconds}秒，普通移动{action.travelMetres}米。</p>
    <p>{attack[action.attackKind]}；原贡献{displayNumber(action.rawContribution)}，原减势{displayNumber(action.rawReduction)}。</p>
    {action.supportId && <p>实际消耗同一枚独立护片，磨损{action.supportWearPaid}；{action.succeeded ? "本次施术成功，仍须后续合格动作才会实际应用。" : "本次施术未建立影响，已付成本保留。"}</p>}
    {action.enemyChargeId && <p>对手实际消耗一枚原刻片，已经发生的攻击与费用保留。</p>}
    {action.fallbackReason && <p>{fallback[action.fallbackReason] ?? "本次按现场条件采用普通替代，已付成本保留。"}</p>}
    {action.resisted && <p>对手已经实际抵抗，本次已付灵性、精神与实物不退。</p>}
    {action.windowsApplied.map((window, index) => <p key={`${window.kind}-${index}`}>{window.kind === "DIVISION" ? `先前付费的分场控制现已为本人这次未结算身体行动增加${displayNumber(window.amount)}。` : `先前付费的余波控制现已为这次身体或弧光冲击减去${displayNumber(window.amount)}贡献；没有取消原攻击与费用。`}同一作用已经用尽。</p>)}
    <p>本槽后本人精神{action.playerMindAfter}、灵性{action.playerSpiritualityAfter}；对手灵性{action.enemySpiritualityAfter}。</p>
  </li>)}</ol>;
}

function HandOfOrderRoundFacts({ outcome, consequenceDomain, characterName }: { outcome: HandOfOrderPublicRoundOutcome; consequenceDomain: SliceCombatRound["consequenceDomain"]; characterName?: string }) {
  const windows = [outcome.division, outcome.aftermath].filter(window => window !== null);
  return <section aria-label="秩序之手本回合实际记录">
    <h3>本人待执行动作、实际冲击与有限护片</h3>
    <p>回合结束：本人健康{outcome.playerHealthAfter}、精神{outcome.playerMindAfter}、灵性{outcome.playerSpiritualityAfter}；对手健康{outcome.enemyHealth}、精神{outcome.enemyMind}、灵性{outcome.enemySpirituality}。</p>
    <p>本回合实际经过{outcome.elapsedSeconds}秒；回合结算时现场时钟{outcome.siteAfter.clockSeconds}秒，本人累计普通移动{outcome.siteAfter.playerTravelMetres}米，对手累计普通移动{outcome.enemyTravelMetres}米。{outcome.continuing ? "交战仍在继续，未用作用按原截止时间保留；到期即止。" : outcome.playerHealthAfter > 0 ? "冲突已经停止，随后沿普通路实际走4米、经过4秒回到室外。" : "本人原身体已经死亡，留在原处，不能步行离场。"}</p>
    <p>独立护片余{outcome.supportPieces.filter(piece => piece.status === "HELD").length}/{outcome.supportPieces.length}枚，累计实际磨损{outcome.supportPieces.reduce((total, piece) => total + piece.wear, 0)}；对手原刻片余{outcome.enemyCharges.filter(piece => piece.status === "HELD").length}/{outcome.enemyCharges.length}枚。原护板当前完整度{outcome.guardPlateAfter.integrity}。</p>
    <p>本人现存伤势{outcome.playerInjuriesAfter.length}处，伤势风险{outcome.playerRiskAfter}；对手伤势{outcome.enemyInjuries.length}处，伤势风险{outcome.enemyRisk}。对手{outcome.enemyStatus === "DEAD" ? "已死亡" : outcome.enemyStatus === "SURRENDERED" ? "已自主停止抵抗" : "仍可抵抗"}，唯一原杖{outcome.weaponLocation === "HAND" ? "仍由对手持有" : "留在旁院原地"}。</p>
    <p>{consequenceDomain === "BODY" ? "本回合按实际身体打击或弧光冲击结算身体伤势。" : consequenceDomain === "MENTAL" ? "本回合只结算实际精神压力，不生成身体伤口。" : "本回合没有实际致伤来源，不掷身体伤势盘。"}分场控制只处理本人下一次尚未结算身体行动；余波控制不削减精神攻击。原伤、死亡、时间与已付费用均不改写。</p>
    {windows.map(window => <p key={window.kind}>{window.kind === "DIVISION" ? "本人下一身体行动的35加成" : "下一身体或弧光冲击的至多30减轻"}，结算时还剩{Math.max(0, window.expiresAt - outcome.siteAfter.clockSeconds)}秒，仅可应用{window.remaining}次。</p>)}
    {outcome.expiredWindows.length > 0 && <p>本回合{outcome.expiredWindows.length}份未用作用已到期，成本保留。</p>}
    {outcome.cancelledWindows.length > 0 && <p>冲突停止时撤销{outcome.cancelledWindows.length}份未用作用，已付费用与护片不退。</p>}
    <HandOfOrderActionSequence actions={[...outcome.playerActions, ...outcome.enemyActions].sort((a, b) => a.order - b.order)} {...(characterName ? { characterName } : {})}/>
  </section>;
}

function HandOfOrderCombatFacts({ value, state }: { value: HandOfOrderCombatProjection; state: SliceProjection }) {
  const policy = state.handOfOrder.encounter.policy;
  return <section className="slice-notice" aria-label="秩序之手本回合实际资源">
    <h3>当前身体、原护板与有限护片</h3>
    <p>本人健康{state.health}/{state.maxHealth} · 精神{state.mind}/{state.maxMind} · 灵性{state.spirituality}/{state.maxSpirituality}；{value.enemyName}健康{value.enemyHealth}/100 · 精神{value.enemyMind}/100 · 独立灵性{value.enemySpirituality}/120。</p>
    <p>本次独立护片余{value.supportPieces.filter(piece => piece.status === "HELD").length}/{value.supportPieces.length}枚，累计实际磨损{value.supportPieces.reduce((total, piece) => total + piece.wear, 0)}；对手原刻片余{value.enemyCharges.filter(piece => piece.status === "HELD").length}/{value.enemyCharges.length}枚。原护板当前完整度{value.guardPlate?.integrity ?? 0}。</p>
    <p>双方实际相距{value.enemyDistanceMetres}米，普通出口还须步行{value.exitMetres}米；现场时钟{value.clockSeconds}秒，本人累计普通移动{value.playerTravelMetres}米，对手累计普通移动{value.enemyTravelMetres}米。原杖{value.weaponLocation === "HAND" ? "仍由布拉姆持有" : "留在旁院原地"}。</p>
    <p>薇娜与米拉已在交战区外；原卡斯帕及此前投降者留在旧场。本场双方每轮最多{value.maxActionCount}次行动，次数与能力按公开轮盘结算。</p>
    <p>本场选择：{policy === "ALL" ? "允许两项新能力" : policy === "DIVISION" ? "只允许分场控制与继承能力" : policy === "AFTERMATH" ? "只允许余波控制与继承能力" : "只作普通行动"}。新术各实耗8灵性、2精神、一枚护片；失败总耗4精神，原费用与磨损保留。</p>
    {value.windows.map(window => <p key={window.kind}>{window.kind === "DIVISION" ? "本人下一未结算身体行动的35加成" : "下一未结算身体或弧光冲击的至多30减轻"}还剩{window.remainingSeconds}秒，可用{window.remaining}次；期限按现场实际经过时间计算。</p>)}
    <HandOfOrderActionSequence actions={value.lastActionSequence} characterName={state.character.name}/>
    <p>{handOfOrderProse(value.summary, state.character.name)}</p>
  </section>;
}


