function Ending({
  state,
  onInspect,
  onTitle,
  onContinue,
  busy,
  error,
  onRetry,
}: {
  state: SliceProjection;
  onInspect: () => void;
  onTitle: () => void;
  onContinue: () => void;
  busy: boolean;
  error: SliceError | null;
  onRetry: () => void;
}) {
  const ending = state.ending!;
  const canContinue = state.status === "SLICE_COMPLETE" && ending.kind !== "DEATH";
  return (
    <div className="slice-ending">
      <section className="slice-ending-intro slice-paper">
        <div className="slice-eyebrow">
          {ending.kind === "DEATH" ? "只读封存卷宗" : "首案已经收尾"}
        </div>
        <h1>{ending.title}</h1>
        <p>{ending.summary}</p>
        <div
          className="slice-row"
          style={{ justifyContent: "center", marginTop: 24 }}
        >
          {canContinue && (
            <button className="slice-button primary" disabled={busy || error !== null} onClick={onContinue}>
              {busy ? "正在结算并保存…" : "继续生活"}
            </button>
          )}
          <button className="slice-button quiet" disabled={busy || error !== null} onClick={onInspect}>
            查看卷宗
          </button>
          <button className="slice-button quiet" disabled={busy || error !== null} onClick={onTitle}>
            返回标题
          </button>
        </div>
        {busy && <p role="status">正在结算并保存，请稍候。</p>}
        {error && <ErrorNotice error={error} onRetry={onRetry} busy={busy} />}
      </section>
      <div className="slice-ending-grid">
        {[
          { title: "工人命运", text: ending.workers },
          { title: "责任与证据", text: ending.accountability },
          { title: "危险物去向", text: ending.hazard },
          { title: "人物关系", text: ending.relationship },
        ].map((axis) => (
          <section className="slice-paper" key={axis.title}>
            <h3>{axis.title}</h3>
            <p>{axis.text}</p>
          </section>
        ))}
      </div>
      {canContinue && (
        <p className="slice-notice" style={{ marginTop: 24 }}>
          继续生活不消耗行动。首案结果会留在卷宗里，已经发生的后果也会延续。
        </p>
      )}
    </div>
  );
}

